  1→import { HttpException, HttpStatus } from '@nestjs/common';
  2→import { ConfigService } from '@nestjs/config';
  3→import { DelegatedRoutingClient } from './delegated-routing.client';
  4→
  5→// Mock global fetch
  6→const mockFetch = jest.fn();
  7→global.fetch = mockFetch;
  8→
  9→function createMockResponse(
 10→  status: number,
 11→  opts: { body?: string; buffer?: ArrayBuffer; headers?: Record<string, string> } = {}
 12→): Response {
 13→  const { body = '', buffer, headers = {} } = opts;
 14→  const headerMap = new Map(Object.entries(headers));
 15→  return {
 16→    ok: status >= 200 && status < 300,
 17→    status,
 18→    headers: { get: (key: string) => headerMap.get(key) ?? null },
 19→    text: jest.fn().mockResolvedValue(body),
 20→    arrayBuffer: jest.fn().mockResolvedValue(buffer ?? new ArrayBuffer(0)),
 21→  } as unknown as Response;
 22→}
 23→
 24→describe('DelegatedRoutingClient', () => {
 25→  let client: DelegatedRoutingClient;
 26→  let configService: ConfigService;
 27→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
 28→  let delaySpy: jest.SpyInstance<Promise<void>, [ms: number], any>;
 29→
 30→  beforeEach(() => {
 31→    jest.restoreAllMocks();
 32→    mockFetch.mockReset();
 33→
 34→    configService = {
 35→      get: jest.fn().mockReturnValue('https://routing.example.com'),
 36→    } as unknown as ConfigService;
 37→
 38→    client = new DelegatedRoutingClient(configService);
 39→
 40→    // Eliminate real delays by making delay() resolve instantly
 41→    delaySpy = jest.spyOn(client as never, 'delay' as never).mockResolvedValue(undefined as never);
 42→  });
 43→
 44→  describe('constructor', () => {
 45→    it('reads DELEGATED_ROUTING_URL from config', () => {
 46→      expect(configService.get).toHaveBeenCalledWith(
 47→        'DELEGATED_ROUTING_URL',
 48→        'https://delegated-ipfs.dev'
 49→      );
 50→    });
 51→  });
 52→
 53→  describe('publish', () => {
 54→    const ipnsName = 'k51qzi5uqu5dg12345';
 55→    const recordBytes = new Uint8Array([1, 2, 3]);
 56→
 57→    it('publishes successfully on first attempt', async () => {
 58→      mockFetch.mockResolvedValueOnce(createMockResponse(200));
 59→
 60→      await client.publish(ipnsName, recordBytes);
 61→
 62→      expect(mockFetch).toHaveBeenCalledTimes(1);
 63→      const [url, init] = mockFetch.mock.calls[0];
 64→      expect(url).toBe(`https://routing.example.com/routing/v1/ipns/${ipnsName}`);
 65→      expect(init.method).toBe('PUT');
 66→      expect(init.headers['Content-Type']).toBe('application/vnd.ipfs.ipns-record');
 67→    });
 68→
 69→    it('throws BAD_GATEWAY on non-retryable HTTP error', async () => {
 70→      mockFetch.mockResolvedValue(createMockResponse(500, { body: 'Internal Server Error' }));
 71→
 72→      const error = await client.publish(ipnsName, recordBytes).catch((e) => e);
 73→
 74→      expect(error).toBeInstanceOf(HttpException);
 75→      expect(error.getStatus()).toBe(HttpStatus.BAD_GATEWAY);
 76→      // Should not retry — only one fetch call
 77→      expect(mockFetch).toHaveBeenCalledTimes(1);
 78→    });
 79→
 80→    it('retries on network errors with exponential backoff', async () => {
 81→      mockFetch
 82→        .mockRejectedValueOnce(new Error('fetch failed'))
 83→        .mockRejectedValueOnce(new Error('fetch failed'))
 84→        .mockResolvedValueOnce(createMockResponse(200));
 85→
 86→      await client.publish(ipnsName, recordBytes);
 87→
 88→      expect(mockFetch).toHaveBeenCalledTimes(3);
 89→      // Delay called twice (attempts 0 and 1)
 90→      expect(delaySpy).toHaveBeenCalledTimes(2);
 91→      expect(delaySpy).toHaveBeenNthCalledWith(1, 1000); // 1000 * 2^0
 92→      expect(delaySpy).toHaveBeenNthCalledWith(2, 2000); // 1000 * 2^1
 93→    });
 94→
 95→    it('throws BAD_GATEWAY after exhausting retries on network errors', async () => {
 96→      mockFetch.mockRejectedValue(new Error('fetch failed'));
 97→
 98→      const error = await client.publish(ipnsName, recordBytes).catch((e) => e);
 99→
100→      expect(error).toBeInstanceOf(HttpException);
101→      expect(error.getStatus()).toBe(HttpStatus.BAD_GATEWAY);
102→      expect(mockFetch).toHaveBeenCalledTimes(3);
103→      // Delay called for attempts 0 and 1, not for last attempt
104→      expect(delaySpy).toHaveBeenCalledTimes(2);
105→    });
106→
107→    it('retries on 429 with Retry-After header', async () => {
108→      mockFetch
109→        .mockResolvedValueOnce(createMockResponse(429, { headers: { 'Retry-After': '2' } }))
110→        .mockResolvedValueOnce(createMockResponse(200));
111→
112→      await client.publish(ipnsName, recordBytes);
113→
114→      expect(mockFetch).toHaveBeenCalledTimes(2);
115→      expect(delaySpy).toHaveBeenCalledWith(2000); // 2 seconds from Retry-After
116→    });
117→
118→    it('skips sleeping on 429 on last retry attempt', async () => {
119→      mockFetch.mockResolvedValue(createMockResponse(429, { headers: { 'Retry-After': '5' } }));
120→
121→      const error = await client.publish(ipnsName, recordBytes).catch((e) => e);
122→
123→      expect(error).toBeInstanceOf(HttpException);
124→      expect(mockFetch).toHaveBeenCalledTimes(3);
125→      // Should only delay for first 2 attempts, skip delay on last
126→      expect(delaySpy).toHaveBeenCalledTimes(2);
127→    });
128→
129→    it('uses abort signal for timeout', async () => {
130→      mockFetch.mockResolvedValueOnce(createMockResponse(200));
131→
132→      await client.publish(ipnsName, recordBytes);
133→
134→      const [, init] = mockFetch.mock.calls[0];
135→      expect(init.signal).toBeInstanceOf(AbortSignal);
136→    });
137→  });
138→
139→  describe('resolve', () => {
140→    const ipnsName = 'k51qzi5uqu5dg12345';
141→    const testBuffer = new Uint8Array([10, 20, 30]).buffer;
142→
143→    function okResponse() {
144→      return {
145→        ok: true,
146→        status: 200,
147→        headers: { get: () => null },
148→        arrayBuffer: jest.fn().mockResolvedValue(testBuffer),
149→      } as unknown as Response;
150→    }
151→
152→    it('resolves successfully and returns Uint8Array', async () => {
153→      mockFetch.mockResolvedValueOnce(okResponse());
154→
155→      const result = await client.resolve(ipnsName);
156→
157→      expect(result).toBeInstanceOf(Uint8Array);
158→      expect(mockFetch).toHaveBeenCalledTimes(1);
159→      const [url, init] = mockFetch.mock.calls[0];
160→      expect(url).toBe(`https://routing.example.com/routing/v1/ipns/${ipnsName}`);
161→      expect(init.method).toBe('GET');
162→      expect(init.headers.Accept).toBe('application/vnd.ipfs.ipns-record');
163→    });
164→
165→    it('returns null for 404 (IPNS name not found)', async () => {
166→      mockFetch.mockResolvedValueOnce(createMockResponse(404));
167→
168→      const result = await client.resolve(ipnsName);
169→
170→      expect(result).toBeNull();
171→      expect(mockFetch).toHaveBeenCalledTimes(1);
172→    });
173→
174→    it('throws BAD_GATEWAY on non-retryable HTTP error', async () => {
175→      mockFetch.mockResolvedValue(createMockResponse(500, { body: 'error' }));
176→
177→      const error = await client.resolve(ipnsName).catch((e) => e);
178→
179→      expect(error).toBeInstanceOf(HttpException);
180→      expect(error.getStatus()).toBe(HttpStatus.BAD_GATEWAY);
181→      expect(mockFetch).toHaveBeenCalledTimes(1);
182→    });
183→
184→    it('retries on network errors', async () => {
185→      mockFetch
186→        .mockRejectedValueOnce(new Error('network error'))
187→        .mockResolvedValueOnce(okResponse());
188→
189→      const result = await client.resolve(ipnsName);
190→
